    atts = req["attachments"]
    if not isinstance(atts, list) or len(atts) > 8:
        raise ValueError
    for att in atts:
        if not isinstance(att, dict):
            raise ValueError
        if set(att.keys()) != {"filename", "content_type", "content_b64"}:
            raise ValueError
        fn = att["filename"]
        if not isinstance(fn, str) or not fn:
            raise ValueError
        if "/" in fn or "\\" in fn:
            raise ValueError
