        if not isinstance(ct, str) or not ct.isascii():
            raise ValueError
        if not re.match(r"^[a-zA-Z0-9!#$%^&*()+_=.-]+/[a-zA-Z0-9!#$%^&*()+_=.-]+$", ct):
            raise ValueError
