        hdr.append("Content-Type: text/plain; charset=utf-8")
        header = "\n".join(hdr) + "\n\n"
        message = header + body
        # Ensure the message ends with a newline
        if not message.endswith("\n"):
            message += "\n"
        return message.encode("utf-8")

