    if not isinstance(req, dict):
        raise ValueError
    if set(req.keys()) != {"from", "to", "subject", "date",
                           "message_id", "body", "attachments"}:
        raise ValueError
    if not _valid_mailbox(req["from"]):
        raise ValueError
    to = req["to"]
    if not isinstance(to, list) or not (1 <= len(to) <= 8):
        raise ValueError
    for entry in to:
        if not _valid_mailbox(entry):
            raise ValueError
    subj = req["subject"]
    if not isinstance(subj, str) or not subj or "\n" in subj or "\r" in subj:
        raise ValueError
    d = req["date"]
    if not isinstance(d, int) or isinstance(d, bool):
        raise ValueError
    if not isinstance(req["message_id"], str) or not _MSGID_RE.match(req["message_id"]):
        raise ValueError
    if not isinstance(req["body"], str):
        raise ValueError
    atts = req["attachments"]
    if not isinstance(atts, list) or len(atts) > 8:
        raise ValueError
    for a in atts:
        if not isinstance(a, dict):
            raise ValueError
        if set(a.keys()) != {"filename", "content_type", "content_b64"}:
            raise ValueError
        if not isinstance(a["filename"], str) or not a["filename"]:
            raise ValueError
        if "/" in a["filename"] or "\\" in a["filename"]:
            raise ValueError
        if not isinstance(a["content_type"], str) or not a["content_type"].isascii():
            raise ValueError
        if not re.match(r"^[a-zA-Z]+/[a-zA-Z0-9.+-]+", a["content_type"]):
            raise ValueError
        b64 = a["content_b64"]
        if not isinstance(b64, str) or not b64.isascii():
            raise ValueError
        try:
            dec = base64.b64decode(b64 + "=" * ((4 - len(b64) % 4) % 4), validate=True)
        except Exception:
            raise ValueError
        if len(dec) > 65536:
            raise ValueError


def _rfc2047_subject(s):
    if s.isascii():
        return s
    enc = base64.b64encode(s.encode("utf-8")).decode("ascii")
    return f"=?UTF-8?B?{enc}?="


def _rfc2231_filename(fn):
    if fn.isascii():
        return f'filename="{fn}"'
    data = fn.encode("utf-8")
    safe = set(range(97, 123)) | set(range(65, 91)) | set(range(48, 58)) | {45, 46, 95, 126}
    percent = "".join(chr(c) if c in safe else f"%{c:02X}" for c in data)
    return f"filename*=UTF-8''{percent}"


def _date_str(epoch):
    return email.utils.formatdate(epoch, usegmt=True)


def _wrap_b64(b64, n=76):
    return "\n".join(b64[i:i+n] for i in range(0, len(b64), n))


def _build(req):
    frm, to_list, subj, epoch, mid, body, atts = (
        req["from"], req["to"], req["subject"], req["date"],
        req["message_id"], req["body"], req["attachments"],
    )
    subj_enc = _rfc2047_subject(subj)
    date_str = _date_str(epoch)
    to_str = ", ".join(to_list)
    hdr = [
        f"From: {frm}",
        f"To: {to_str}",
        f"Subject: {subj_enc}",
        f"Date: {date_str}",
        f"Message-ID: {mid}",
        "MIME-Version: 1.0",
    ]

    # Build the text/plain part content (7-bit clean)
    body_bytes = body.encode("utf-8")
    ascii_body = body.isascii()
    if ascii_body:
        body_part = body
        if not body_part.endswith("\n"):
            body_part += "\n"
        cte = None
    else:
        cte = "base64"
        body_part = _wrap_b64(base64.b64encode(body_bytes).decode("ascii"))

    if not atts:
        ct = "Content-Type: text/plain; charset=utf-8"
        if cte:
            ct += f"\nContent-Transfer-Encoding: {cte}"
            hdr.append(ct)
        else:
            hdr.append(ct)
        header = "\n".join(hdr) + "\n\n"
        msg = header + body_part
        if not msg.endswith("\n"):
            msg += "\n"
        return msg.encode("ascii")

    hdr.append(f'Content-Type: multipart/mixed; boundary="{_BWD}"')
    header = "\n".join(hdr) + "\n\n"
    parts = []
    tp = "Content-Type: text/plain; charset=utf-8"
    if cte:
        tp += f"\nContent-Transfer-Encoding: {cte}"
    parts.append(tp + "\n\n" + body_part)
