            f"Content-Type: {att['content_type']}\n"
            f"Content-Disposition: attachment; {fnp}\n"
            "Content-Transfer-Encoding: base64\n"
            f"\n{wrapped}\n"
        )
    msg = header + "\n".join(f"--{_BWD}\n{p}" for p in parts) + f"\n--{_BWD}--\n"
    return msg.encode("ascii")


def main():
    try:
        raw = sys.stdin.buffer.read()
        if not raw:
            raise ValueError
        req = json.loads(raw.decode("utf-8"))
        _validate(req)
        msg_bytes = _build(req)
        if any(b > 127 for b in msg_bytes):
            raise ValueError
        for ln in msg_bytes.split(b"\n"):
            if len(ln) > 998:
                raise ValueError
        res = {
            "format": "eml",
            "message_b64": base64.b64encode(msg_bytes).decode("ascii"),
            "sha256": hashlib.sha256(msg_bytes).hexdigest(),
        }
        sys.stdout.write(json.dumps(res))
    except Exception:
        sys.stdout.write(json.dumps({"error": "invalid_request"}))


